"""Checkout orders through PayPal's official Python Server SDK (generated by APIMatic)."""

import json
import uuid
from dataclasses import dataclass
from decimal import Decimal
from functools import lru_cache

from paypalserversdk.configuration import Environment
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.amount_with_breakdown import AmountWithBreakdown
from paypalserversdk.models.checkout_payment_intent import CheckoutPaymentIntent
from paypalserversdk.models.money import Money
from paypalserversdk.models.order_request import OrderRequest
from paypalserversdk.models.payment_source import PaymentSource
from paypalserversdk.models.paypal_experience_user_action import PaypalExperienceUserAction
from paypalserversdk.models.paypal_wallet import PaypalWallet
from paypalserversdk.models.paypal_wallet_context_shipping_preference import PaypalWalletContextShippingPreference
from paypalserversdk.models.paypal_wallet_experience_context import PaypalWalletExperienceContext
from paypalserversdk.models.purchase_unit_request import PurchaseUnitRequest
from paypalserversdk.models.refund_request import RefundRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from app.config import get_settings

CENT = Decimal("0.01")


@dataclass
class Capture:
    order_id: str
    capture_id: str
    status: str  # COMPLETED | PENDING | DECLINED ...
    amount: Decimal  # US dollars (a payment in another currency is converted at PayPal's rate)
    fee: Decimal  # US dollars
    payment_method: str  # paypal | venmo | ...
    currency: str = "USD"  # what the buyer paid in
    original_amount: Decimal | None = None  # in that currency
    exchange_rate: Decimal | None = None  # PayPal's, to US dollars


def in_dollars(capture: dict) -> tuple[Decimal, Decimal, str, Decimal | None, Decimal | None]:
    """(gross, fee, currency, amount in that currency, rate) from a capture or a capture webhook's resource. In
    another currency PayPal converts what's left after its fee: the dollars received are its `receivable_amount`,
    the gross is the paid amount at PayPal's rate, and the fee is the difference, so the books match PayPal."""
    amount = Decimal(capture["amount"]["value"])
    currency = capture["amount"].get("currency_code", "USD")
    breakdown = capture.get("seller_receivable_breakdown", {})
    fee = Decimal(breakdown.get("paypal_fee", {}).get("value", "0"))
    if currency == "USD" or "exchange_rate" not in breakdown:
        return amount, fee, currency, None, None
    rate = Decimal(breakdown["exchange_rate"]["value"])
    received = Decimal(breakdown["receivable_amount"]["value"])
    gross = (amount * rate).quantize(CENT)
    return gross, gross - received, currency, amount, rate


@lru_cache
def client() -> PaypalServersdkClient:
    s = get_settings()
    return PaypalServersdkClient(
        client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
            o_auth_client_id=s.paypal_client_id, o_auth_client_secret=s.paypal_client_secret
        ),
        environment=Environment.SANDBOX if s.paypal_environment == "sandbox" else Environment.PRODUCTION,
    )


def create_order(*, amount: Decimal, description: str, custom_id: str, reference_id: str, currency: str = "USD") -> str:
    """Create a CAPTURE order the buyer approves in the browser (PayPal, Venmo or Pay Later button)."""
    return create_order_with_link(
        amount=amount, description=description, custom_id=custom_id, reference_id=reference_id, currency=currency
    )[0]


def create_order_with_link(
    *,
    amount: Decimal,
    description: str,
    custom_id: str,
    reference_id: str,
    return_url: str | None = None,
    cancel_url: str | None = None,
    currency: str = "USD",
) -> tuple[str, str | None]:
    """Create a CAPTURE order. With `return_url`, PayPal also gives a link a person can open to approve it
    (used by the public API and agents); afterwards PayPal sends them to `return_url` to finish."""
    payment_source = None
    if return_url:
        payment_source = PaymentSource(
            paypal=PaypalWallet(
                experience_context=PaypalWalletExperienceContext(
                    brand_name="Hearthline",
                    return_url=return_url,
                    cancel_url=cancel_url or return_url,
                    user_action=PaypalExperienceUserAction.PAY_NOW,
                    shipping_preference=PaypalWalletContextShippingPreference.NO_SHIPPING,
                )
            )
        )
    body = OrderRequest(
        intent=CheckoutPaymentIntent.CAPTURE,
        purchase_units=[
            PurchaseUnitRequest(
                amount=AmountWithBreakdown(currency_code=currency, value=f"{amount:.2f}"),
                description=description[:127],
                custom_id=custom_id,
                reference_id=reference_id,
                soft_descriptor="HEARTHLINE",
            )
        ],
        payment_source=payment_source,
    )
    response = client().orders.create_order({"body": body, "paypal_request_id": str(uuid.uuid4())})
    link = next((x.href for x in response.body.links or [] if x.rel in {"payer-action", "approve"}), None)
    return response.body.id, link


def capture_order(order_id: str) -> Capture:
    response = client().orders.capture_order(
        {"id": order_id, "prefer": "return=representation", "paypal_request_id": f"capture-{order_id}"}
    )
    return parse_capture(json.loads(response.text))


def parse_capture(order: dict) -> Capture:
    capture = order["purchase_units"][0]["payments"]["captures"][0]
    gross, fee, currency, original, rate = in_dollars(capture)
    return Capture(
        order_id=order["id"],
        capture_id=capture["id"],
        status=capture["status"],
        amount=gross,
        fee=fee,
        payment_method=next(iter(order.get("payment_source", {"paypal": None})), "paypal"),
        currency=currency,
        original_amount=original,
        exchange_rate=rate,
    )


def refund_capture(capture_id: str, amount: Decimal | None = None) -> str:
    """Refund a captured payment, in full or `amount` of it. Returns PayPal's refund status
    (COMPLETED, PENDING, ...). The request id makes a retry safe."""
    request = {"capture_id": capture_id, "paypal_request_id": f"refund-{capture_id}", "prefer": "return=minimal"}
    if amount is not None:
        request["body"] = RefundRequest(amount=Money(currency_code="USD", value=f"{amount:.2f}"))
        request["paypal_request_id"] = f"refund-{capture_id}-{amount:.2f}"
    response = client().payments.refund_captured_payment(request)
    return json.loads(response.text)["status"]
